import React, { useState, useEffect } from 'react';
import RegisterForm from './RegisterForm';
import './LoginPage.css';

const emailRegex = /^[^\s@]+@[^\s@]+\.[^\s@]+$/;

function LoginPage() {
  const [isRegistering, setIsRegistering] = useState(false);
  const [loginData, setLoginData] = useState({
    email: '',
    password: '',
    rememberMe: false,
  });
  const [error, setError] = useState('');
  const [isLoading, setIsLoading] = useState(false);
  const [showPassword, setShowPassword] = useState(false);
  const [showForgotPassword, setShowForgotPassword] = useState(false);
  const [forgotEmail, setForgotEmail] = useState('');
  const [forgotError, setForgotError] = useState('');
  const [forgotSuccess, setForgotSuccess] = useState('');
  const [successMessage, setSuccessMessage] = useState('');

  // Load saved data and login history from localStorage
  useEffect(() => {
    const savedData = localStorage.getItem('pgLoginData');
    const savedHistory = localStorage.getItem('pgLoginHistory');
    
    if (savedData) {
      try {
        const parsed = JSON.parse(savedData);
        setLoginData((prev) => ({
          ...prev,
          email: parsed.email || '',
          role: parsed.role || 'resident',
          buildingId: parsed.buildingId || '',
          rememberMe: true,
        }));
      } catch (e) {
        console.error('Error loading saved data:', e);
      }
    }

    if (savedHistory) {
      try {
        setLoginHistory(JSON.parse(savedHistory));
      } catch (e) {
        console.error('Error loading history:', e);
      }
    }
  }, []);

  const handleInputChange = (event) => {
    const { name, value, type, checked } = event.target;
    const fieldValue = type === 'checkbox' ? checked : value;
    setLoginData((prev) => ({ ...prev, [name]: fieldValue }));
    if (error) setError('');
  };

  const validateEmail = (email) => emailRegex.test(email);
  const validatePhone = (phone) => phoneRegex.test(phone);

  const addToLoginHistory = (email, role, buildingId, success) => {
    const newEntry = {
      email,
      role,
      buildingId,
      timestamp: new Date().toISOString(),
      success,
    };
    const history = [newEntry, ...loginHistory].slice(0, 10); // Keep last 10 logins
    setLoginHistory(history);
    localStorage.setItem('pgLoginHistory', JSON.stringify(history));
  };

  const handleLoginSubmit = async (event) => {
    event.preventDefault();
    
    if (!loginData.email.trim() || !loginData.password.trim()) {
      setError('Email and password are required.');
      return;
    }

    if (!validateEmail(loginData.email)) {
      setError('Please enter a valid email address.');
      return;
    }

    if (loginData.password.length < 6) {
      setError('Password must be at least 6 characters.');
      return;
    }

    if (!loginData.buildingId) {
      setError('Please select a building.');
      return;
    }

    if (loginData.use2FA && !loginData.phone.trim()) {
      setError('Phone number is required for 2FA.');
      return;
    }

    if (loginData.use2FA && !validatePhone(loginData.phone)) {
      setError('Please enter a valid 10-digit phone number.');
      return;
    }

    setError('');
    setIsLoading(true);

    try {
      // Simulate sending 2FA code
      if (loginData.use2FA) {
        await new Promise((resolve) => setTimeout(resolve, 1000));
        setLoginStep('2fa');
        setTwoFACode('');
      } else {
        // Direct login without 2FA
        await new Promise((resolve) => setTimeout(resolve, 500));
        
        // Save credentials if remember me is checked
        if (loginData.rememberMe) {
          localStorage.setItem('pgLoginData', JSON.stringify({
            email: loginData.email,
            role: loginData.role,
            buildingId: loginData.buildingId,
          }));
        } else {
          localStorage.removeItem('pgLoginData');
        }

        addToLoginHistory(loginData.email, loginData.role, loginData.buildingId, true);
        // Replace with real authentication API call
        // const response = await loginUser(loginData);
        // Store token and redirect
      }
    } catch (err) {
      addToLoginHistory(loginData.email, loginData.role, loginData.buildingId, false);
      setError(err.message || 'Login failed. Please try again.');
    } finally {
      setIsLoading(false);
    }
  };

  const handleVerify2FA = async (event) => {
    event.preventDefault();
    setTwoFAError('');

    if (!twoFACode.trim()) {
      setTwoFAError('Please enter the 2FA code.');
      return;
    }

    if (twoFACode.length !== 6) {
      setTwoFAError('2FA code must be 6 digits.');
      return;
    }

    setIsLoading(true);
    try {
      // Replace with real 2FA verification API call
      // await verify2FA(loginData.email, twoFACode);
      await new Promise((resolve) => setTimeout(resolve, 500));

      // Save credentials if remember me is checked
      if (loginData.rememberMe) {
        localStorage.setItem('pgLoginData', JSON.stringify({
          email: loginData.email,
          role: loginData.role,
          buildingId: loginData.buildingId,
        }));
      } else {
        localStorage.removeItem('pgLoginData');
      }

      addToLoginHistory(loginData.email, loginData.role, loginData.buildingId, true);
      // Redirect to dashboard
    } catch (err) {
      setTwoFAError(err.message || '2FA verification failed.');
      addToLoginHistory(loginData.email, loginData.role, loginData.buildingId, false);
    } finally {
      setIsLoading(false);
    }
  };

  const handleForgotPassword = async (event) => {
    event.preventDefault();
    setForgotError('');
    setForgotSuccess('');

    if (!forgotEmail.trim()) {
      setForgotError('Please enter your email address.');
      return;
    }

    if (!validateEmail(forgotEmail)) {
      setForgotError('Please enter a valid email address.');
      return;
    }

    setIsLoading(true);
    try {
      // Replace with real password reset API call
      // await sendPasswordReset(forgotEmail);
      await new Promise((resolve) => setTimeout(resolve, 1000));
      setForgotSuccess('Password reset link sent to your email!');
      setTimeout(() => setShowForgotPassword(false), 2000);
    } catch (err) {
      setForgotError(err.message || 'Failed to send reset link.');
    } finally {
      setIsLoading(false);
    }
  };

  return (
    <div className="login-page">
      <div className="login-container">
        <div className="login-card">
          <div className="login-card-header">
            <div className="pg-logo">
              <span className="logo-icon">🏢</span>
              <h1>PG Management</h1>
            </div>
            <p className="tagline">Professional Paying Guest Management System</p>
          </div>

          <div className="login-header">
            <h2>{isRegistering ? 'Create an Account' : loginStep === '2fa' ? 'Verify with 2FA' : 'Sign In'}</h2>
            {!isRegistering && (
              <button
                type="button"
                className="toggle-button"
                onClick={() => {
                  setIsRegistering(true);
                  setLoginStep('credentials');
                }}
              >
                New user? Register
              </button>
            )}
          </div>

          {isRegistering ? (
            <RegisterForm onRegistered={() => {
              setIsRegistering(false);
              setLoginStep('credentials');
            }} />
          ) : loginStep === '2fa' ? (
            <form className="login-form" onSubmit={handleVerify2FA}>
              <div className="verification-container">
                <h3 className="verification-title">Two-Factor Authentication</h3>
                <p className="verification-text">
                  We've sent a 6-digit code to <strong>{loginData.phone}</strong>
                </p>

                <div className="form-group">
                  <label htmlFor="twoFACode">Enter 6-digit Code</label>
                  <input
                    id="twoFACode"
                    type="text"
                    value={twoFACode}
                    onChange={(e) => {
                      setTwoFACode(e.target.value.replace(/\D/g, '').slice(0, 6));
                      setTwoFAError('');
                    }}
                    placeholder="000000"
                    maxLength="6"
                    disabled={isLoading}
                    required
                    className="otp-input"
                  />
                  {twoFAError && <span className="field-error">{twoFAError}</span>}
                </div>

                <button
                  type="submit"
                  className="primary-button"
                  disabled={isLoading}
                >
                  {isLoading ? 'Verifying...' : 'Verify 2FA'}
                </button>

                <button
                  type="button"
                  className="resend-link"
                  onClick={() => {
                    setLoginStep('credentials');
                    setTwoFACode('');
                  }}
                  disabled={isLoading}
                >
                  Back to Login
                </button>
              </div>
            </form>
          ) : (
            <>
              <form className="login-form" onSubmit={handleLoginSubmit}>
                <div className="role-selector">
                  <label>Login As:</label>
                  <div className="role-buttons">
                    {USER_ROLES.map((role) => (
                      <button
                        key={role.value}
                        type="button"
                        className={`role-button ${loginData.role === role.value ? 'active' : ''}`}
                        onClick={() => handleInputChange({
                          target: { name: 'role', value: role.value, type: 'text' }
                        })}
                      >
                        {role.label}
                      </button>
                    ))}
                  </div>
                </div>

                <div className="form-group">
                  <label htmlFor="email">Email Address</label>
                  <input
                    id="email"
                    name="email"
                    type="email"
                    value={loginData.email}
                    onChange={handleInputChange}
                    placeholder="you@example.com"
                    disabled={isLoading}
                    required
                    autoComplete="email"
                  />
                </div>

                <div className="form-group">
                  <label htmlFor="password">Password</label>
                  <div className="password-input-wrapper">
                    <input
                      id="password"
                      name="password"
                      type={showPassword ? 'text' : 'password'}
                      value={loginData.password}
                      onChange={handleInputChange}
                      placeholder="Enter your password"
                      disabled={isLoading}
                      required
                      autoComplete="current-password"
                    />
                    <button
                      type="button"
                      className="password-toggle"
                      onClick={() => setShowPassword(!showPassword)}
                      disabled={isLoading}
                      title={showPassword ? 'Hide password' : 'Show password'}
                    >
                      {showPassword ? '👁️' : '👁️‍🗨️'}
                    </button>
                  </div>
                </div>

                <div className="form-group">
                  <label htmlFor="buildingId">Building/Hostel</label>
                  <select
                    id="buildingId"
                    name="buildingId"
                    value={loginData.buildingId}
                    onChange={handleInputChange}
                    disabled={isLoading}
                    required
                  >
                    <option value="">Select a building</option>
                    {BUILDINGS.map((building) => (
                      <option key={building.id} value={building.id}>
                        {building.name}
                      </option>
                    ))}
                  </select>
                </div>

                <div className="form-group">
                  <label htmlFor="twoFAToggle" className="checkbox-label">
                    <input
                      id="twoFAToggle"
                      name="use2FA"
                      type="checkbox"
                      checked={loginData.use2FA}
                      onChange={handleInputChange}
                      disabled={isLoading}
                    />
                    <span>Enable 2-Factor Authentication</span>
                  </label>
                </div>

                {loginData.use2FA && (
                  <div className="form-group">
                    <label htmlFor="phone">Phone Number (for 2FA)</label>
                    <input
                      id="phone"
                      name="phone"
                      type="tel"
                      value={loginData.phone}
                      onChange={handleInputChange}
                      placeholder="10-digit number"
                      maxLength="10"
                      disabled={isLoading}
                      autoComplete="tel"
                    />
                    <small className="field-hint">Format: 10 digits (e.g., 9876543210)</small>
                  </div>
                )}

                <div className="form-group checkbox-group">
                  <input
                    id="rememberMe"
                    name="rememberMe"
                    type="checkbox"
                    checked={loginData.rememberMe}
                    onChange={handleInputChange}
                    disabled={isLoading}
                  />
                  <label htmlFor="rememberMe">Remember me</label>
                  <button
                    type="button"
                    className="forgot-password-link"
                    onClick={() => setShowForgotPassword(true)}
                    disabled={isLoading}
                  >
                    Forgot password?
                  </button>
                </div>

                {error && <div className="error-message" role="alert">{error}</div>}

                <button
                  type="submit"
                  className="primary-button"
                  disabled={isLoading}
                >
                  {isLoading ? 'Signing In...' : 'Sign In'}
                </button>
              </form>
            </>
          )}
        </div>

        {/* Login History Sidebar */}
        {loginHistory.length > 0 && (
          <div className="login-history-sidebar">
            <h3>Recent Login Activity</h3>
            <div className="history-list">
              {loginHistory.map((entry, index) => (
                <div key={index} className={`history-item ${entry.success ? 'success' : 'failed'}`}>
                  <div className="history-status">{entry.success ? '✓' : '✗'}</div>
                  <div className="history-details">
                    <div className="history-email">{entry.email}</div>
                    <div className="history-role">{entry.role}</div>
                    <div className="history-time">
                      {new Date(entry.timestamp).toLocaleTimeString()}
                    </div>
                  </div>
                </div>
              ))}
            </div>
          </div>
        )}
      </div>

      {/* Forgot Password Modal */}
      {showForgotPassword && (
        <div className="modal-overlay" onClick={() => setShowForgotPassword(false)}>
          <div className="modal-content" onClick={(e) => e.stopPropagation()}>
            <div className="modal-header">
              <h3>Reset Password</h3>
              <button
                type="button"
                className="modal-close"
                onClick={() => setShowForgotPassword(false)}
                disabled={isLoading}
              >
                ✕
              </button>
            </div>

            <form onSubmit={(e) => e.preventDefault()} className="forgot-form">
              <p className="modal-description">
                Enter your email address and we'll send you a link to reset your password.
              </p>

              <div className="form-group">
                <label htmlFor="forgotEmail">Email Address</label>
                <input
                  id="forgotEmail"
                  type="email"
                  value={forgotEmail}
                  onChange={(e) => {
                    setForgotEmail(e.target.value);
                    setForgotError('');
                  }}
                  placeholder="you@example.com"
                  disabled={isLoading}
                  required
                  autoComplete="email"
                />
              </div>

              {forgotError && <div className="error-message" role="alert">{forgotError}</div>}
              {forgotSuccess && <div className="success-message" role="alert">{forgotSuccess}</div>}

              <button
                type="button"
                className="primary-button"
                disabled={isLoading}
                onClick={async () => {
                  setForgotError('');
                  if (!forgotEmail.trim()) {
                    setForgotError('Please enter your email.');
                    return;
                  }
                  if (!validateEmail(forgotEmail)) {
                    setForgotError('Please enter a valid email.');
                    return;
                  }
                  setIsLoading(true);
                  try {
                    await new Promise((r) => setTimeout(r, 1000));
                    setForgotSuccess('Password reset link sent!');
                    setTimeout(() => setShowForgotPassword(false), 2000);
                  } catch (err) {
                    setForgotError('Failed to send reset link.');
                  } finally {
                    setIsLoading(false);
                  }
                }}
              >
                {isLoading ? 'Sending...' : 'Send Reset Link'}
              </button>
            </form>
          </div>
        </div>
      )}
    </div>
  );
}

export default LoginPage;
